import {useCallback, useState} from 'react';

export function useHint() {
    const [hasOverflow, setHasOverflow] = useState(false);

    const handleTextNodeRef = useCallback((node: HTMLDivElement | null) => {
        if (node) {
            setHasOverflow(node.offsetWidth < node.scrollWidth);
        }
    }, []);

    return {
        withHint: hasOverflow,
        handleTextNodeRef,
    };
}
